def has_pair_sum_sorted(a: list[int], target: int) -> bool:
    i, j = 0, len(a) - 1
    while i < j:
        s = a[i] + a[j]
        if s == target:
            return True
        if s < target:
            i += 1
        else:
            j -= 1
    return False
